<?php require '_layout.php';$rows=db()->query("SELECT c.*,COUNT(o.id) AS total_orders,MAX(o.created_at) AS last_order FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id ORDER BY c.id DESC")->fetchAll();admin_header('Data Pelanggan','customers'); ?><div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Nama</th><th>WhatsApp</th><th>Alamat</th><th>Total Pesanan</th><th>Pesanan Terakhir</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['phone']) ?></td><td><?= e($r['address']) ?></td><td><?= (int)$r['total_orders'] ?></td><td><?= e($r['last_order']??'-') ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5">Belum ada data pelanggan.</td></tr><?php endif; ?></tbody></table></div></div><?php admin_footer(); ?>
